-- Üretildi: scripts/aeg-yenile-2026-10-13.py — Anadolu Ekininde Güzeller fotoğraf yenileme.
-- Hiçbir satır SİLİNMEZ. Geri alma: 2026-10-13-anadolu-fotograf-yenile-GERI-AL.sql
BEGIN;
-- güvenlik: eski 9 satır beklenen üründe mi?
DO $$ BEGIN IF (select count(*) from product_images where id between 590 and 598 and product_id=(select id from products where slug='anadolu-ekininde-guzeller')) <> 9 THEN RAISE EXCEPTION 'eski satırlar beklenmedik'; END IF; END $$;
UPDATE product_images SET is_visible = false, sort_order = sort_order + 100 WHERE id IN (590, 591, 592, 593, 594, 595, 596, 597, 598);
-- eski kareler 2008 Nüve / Nucleus sergisine (aynı Cloudinary dosyası, yeniden yükleme yok)
SELECT 'nuve-nucleus-marina-2008', url, 4 + row_number() OVER (ORDER BY id)
FROM product_images WHERE id IN (590, 591, 592, 593, 594, 596, 597, 598) ORDER BY id;
COMMIT;
